'use strict';
const E=window.InsureLens;
const $=(q,base=document)=>base.querySelector(q);
const $$=(q,base=document)=>[...base.querySelectorAll(q)];
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=n=>Number(n).toLocaleString('ko-KR');
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',download:'M12 3v13 M7 11l5 5 5-5 M4 16v5h16v-5',sliders:'M4 4v16 M12 4v16 M20 4v16 M1 8h6 M9 15h6 M17 10h6',arrow:'M5 12h14 M14 7l5 5-5 5',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6',money:'M3 5h18v14H3z M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M6 8h1 M17 16h1',alert:'m12 3 10 18H2z M12 9v5 M12 17v1',chart:'M4 3v17h17 M8 15l4-5 4 2 5-7',check:'M5 12l4 4L19 6',info:'M12 11v6 M12 7v1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',clock:'M12 7v6l4 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',code:'m8 5-6 7 6 7 M16 5l6 7-6 7 M14 3l-4 18',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17v1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',user:'M20 21v-3a5 5 0 0 0-5-5H9a5 5 0 0 0-5 5v3 M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',refresh:'M20 8a8 8 0 1 0 0 8 M20 3v5h-5',send:'m3 3 18 9-18 9 3-9z M6 12h15',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h1 M3 12h1 M3 18h1'};
const icon=name=>`<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths.file}"/></svg></span>`;
const navItems=[['dashboard','grid','분석 개요'],['review','search','검토 대상'],['detail','spark','청구 상세 · AI 설명'],['report','file','분석 보고서'],['about','shield','과제 적합성']];
let savedConfig={};try{savedConfig=JSON.parse(localStorage.getItem('insurelens-settings')||'{}');}catch{}
const state={data:E.sample(),analysis:null,config:{...E.defaults,...savedConfig},source:'가상 보험 청구 데이터',sample:true,selected:null,tab:'dashboard',search:'',type:'all',priority:'all',page:1,explanations:new Map(),reviews:new Map(),version:1,comparison:null,api:false,apiNote:'데모 설명 모드'};
const priorityBadge=p=>`<span class="badge ${p==='높음'?'red':p==='보통'?'amber':'green'}">${p==='높음'?'● ':''}${escapeHTML(p)}</span>`;
const sortedRows=()=>state.analysis.results.slice().sort((a,b)=>b.score-a.score||a.claim_id.localeCompare(b.claim_id));
const selectedRow=()=>state.analysis.results.find(r=>r.claim_id===state.selected)||sortedRows()[0];
const cacheKey=()=>state.version+':'+state.selected+':'+JSON.stringify(state.config);
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500);}
function go(tab){if(state.tab===tab){render();return;}location.hash=tab;}
function heading(title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">INSURANCE INTELLIGENCE</span><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function actions(){return `<button class="button" data-action="settings">${icon('sliders')}분석 기준</button><button class="button primary" data-action="data">${icon('upload')}데이터 불러오기</button>`;}
function sourceStrip(){const a=state.analysis,q=a.quality,first=a.results[0].claim_date,last=a.results.at(-1).claim_date;return `<div class="source-strip"><div class="source-left"><span class="source-icon">${icon('file')}</span><strong>${escapeHTML(state.source)}</strong><span class="badge ${state.sample?'gray':'green'}">${state.sample?'SAMPLE':'CSV'}</span><span class="source-divider"></span><span class="muted">${first.replaceAll('-','.')} — ${last.replaceAll('-','.')}</span><span class="source-status">· ${f(q.clean.length)}건 유효 / ${f(q.rejected.length)}건 제외</span></div><button class="button link" data-action="quality">데이터 품질 보기 ${icon('arrow')}</button></div>`;}
function pipeline(){return `<div class="pipeline">${[['데이터 검증','1'],['과거 기반 특징 추출','2'],['규칙 + 모델 분석','3'],['근거·설명 생성','4'],['담당자 검토','5']].map(([s,n],i)=>`${i?'<span class="pipeline-arrow">›</span>':''}<div class="pipeline-item"><span class="step-number">${n}</span>${s}</div>`).join('')}</div>`;}
function metric(label,value,unit,foot,ico,extra=''){return `<div class="metric ${extra}"><div class="metric-label">${label}${icon(ico)}</div><div class="metric-number">${value}<small>${unit}</small></div><div class="metric-foot">${foot}</div></div>`;}
function metricGrid(){const s=state.analysis.summary;return `<div class="metric-grid">${metric('전체 청구 건수',f(s.count),'건','<span class="accent">✓</span> 검증된 청구 데이터','file')}${metric('전체 청구 금액',(s.total/1e8).toFixed(2),'억 원',E.money(s.total),'money')}${metric('우선 검토 대상',f(s.high),'건',`전체의 ${(s.high/s.count*100).toFixed(1)}% · 높은 검토 우선순위`,'alert','high')}${metric('추가 확인 대상',f(s.medium),'건','보통 우선순위 · 근거 확인 권장','shield')}</div>`;}
function monthlyChart(){const data=Object.entries(state.analysis.summary.monthly).sort(),max=Math.ceil(Math.max(...data.map(x=>x[1]))/50)*50||1,w=620,h=210,left=35,right=15,top=18,bottom=34,plotW=w-left-right,plotH=h-top-bottom;const coords=data.map((d,i)=>[left+i*plotW/Math.max(data.length-1,1),top+plotH*(1-d[1]/max)]),poly=coords.map(p=>p.join(',')).join(' ');return `<div class="chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="월별 청구 건수 추이">${[0,.25,.5,.75,1].map(t=>`<line class="grid-line" x1="${left}" x2="${w-right}" y1="${top+plotH*t}" y2="${top+plotH*t}"/><text x="${left-10}" y="${top+plotH*t+3}" text-anchor="end">${Math.round(max*(1-t))}</text>`).join('')}<path class="area" d="M${left},${top+plotH} L${poly.replaceAll(' ',',L').replaceAll(',L',' L')} L${coords.at(-1)[0]},${top+plotH} Z"/><polyline class="line" points="${poly}"/>${coords.map((p,i)=>`<circle class="point" cx="${p[0]}" cy="${p[1]}" r="3"><title>${data[i][0]}: ${f(data[i][1])}건</title></circle><text x="${p[0]}" y="${h-10}" text-anchor="middle">${Number(data[i][0].slice(5))}월</text>`).join('')}</svg></div>`;}
function donut(){const s=state.analysis.summary,data=[['높음',s.high,'#cda36a'],['보통',s.medium,'#9db5a3'],['낮음',s.low,'#e2ebe4']];let offset=0;return `<div class="donut-wrap"><div class="donut"><svg viewBox="0 0 120 120" role="img" aria-label="검토 우선순위 분포">${data.map(([label,value,color])=>{const length=value/s.count*301.593,start=offset;offset+=length;return `<circle cx="60" cy="60" r="48" fill="none" stroke="${color}" stroke-width="13" stroke-dasharray="${length} ${301.593-length}" stroke-dashoffset="${-start}"><title>${label} ${value}건</title></circle>`;}).join('')}</svg><div class="donut-center">${f(s.count)}<span>전체 청구</span></div></div><div class="donut-legend">${data.map(([label,n,color])=>`<div><span class="legend-square" style="background:${color}"></span>${label}<strong>${f(n)}</strong></div>`).join('')}</div></div>`;}
function typeBars(){const entries=Object.entries(state.analysis.summary.types).sort((a,b)=>b[1]-a[1]),max=Math.max(...entries.map(x=>x[1]));return `<div class="horizontal-bars">${entries.map(([type,n])=>`<div class="bar-row"><span title="${escapeHTML(type)}">${escapeHTML(type.slice(0,4))}</span><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><span>${f(n)}</span></div>`).join('')}</div>`;}
function claimTable(rows,full=false){return `<div class="table-wrap"><table><thead><tr><th>청구 ID</th><th>보험 유형</th><th>청구 금액</th><th>검토 점수</th><th>우선순위</th>${full?'<th>규칙 / 모델</th>':''}<th>주요 탐지 근거</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="table-button claim-id" data-select="${escapeHTML(r.claim_id)}">${escapeHTML(r.claim_id)}</button></td><td>${escapeHTML(r.insurance_type)}</td><td>${E.money(r.amount)}</td><td class="score-cell ${r.priority==='높음'?'high':''}">${r.score.toFixed(1)}</td><td>${priorityBadge(r.priority)}</td>${full?`<td>${r.ruleScore.toFixed(0)} / ${r.mlScore===null?'—':r.mlScore.toFixed(0)}</td>`:''}<td>${r.reasons.slice(0,2).map(reason=>`<span class="tag">${reason}</span>`).join('')||'<span class="muted">규칙 탐지 없음</span>'}${r.reasons.length>2?`<span class="muted">+${r.reasons.length-2}</span>`:''}</td><td><button class="table-button" data-select="${escapeHTML(r.claim_id)}" aria-label="${escapeHTML(r.claim_id)} 상세 보기">${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">조건에 맞는 청구가 없습니다.</td></tr>'}</tbody></table></div>`;}
function briefing(){const s=state.analysis.summary,top=sortedRows()[0],frequencies={};state.analysis.results.forEach(r=>r.rules.filter(x=>x.hit&&x.id!=='combined').forEach(x=>frequencies[x.name]=(frequencies[x.name]||0)+1));const common=Object.entries(frequencies).sort((a,b)=>b[1]-a[1])[0];return `<section class="panel briefing"><div class="briefing-head">${icon('spark')}<h2>오늘의 검토 브리핑</h2><span class="badge">분석 요약</span></div><p>전체 <strong>${f(s.count)}건</strong> 중 <strong>${f(s.high)}건</strong>이 우선 검토 대상으로 분류되었습니다.${common?` 가장 자주 확인된 패턴은 <strong>${common[0]}</strong>입니다.`:' 현재 설정에서 반복적인 규칙 패턴은 확인되지 않았습니다.'}</p><div class="briefing-separator"></div><ul><li>점수순으로 근거를 확인해 검토를 시작하세요.</li><li>동일 진료 유형의 이전 청구와 비교합니다.</li><li>정상적인 고액·반복 진료 가능성도 확인하세요.</li></ul><button class="button" data-select="${escapeHTML(top.claim_id)}">첫 번째 청구 검토하기 ${icon('arrow')}</button></section>`;}
function qualityHTML(){const q=state.analysis.quality;return `<section class="panel section-gap" id="quality-section"><div class="panel-head"><div><h2>데이터 검증 결과</h2><p>원본 ${f(q.inputCount)}건 · 유효 ${f(q.clean.length)}건 · 제외 ${f(q.rejected.length)}건</p></div><span class="badge ${q.rejected.length?'amber':'green'}">${q.rejected.length?'일부 행 제외':'검증 완료'}</span></div><div class="panel-body"><p class="muted" style="font-size:11px">필수값, 날짜, 양수 금액, 중복 청구 ID를 확인했습니다. 같은 날짜의 청구는 서로의 과거 특징에 포함하지 않습니다.</p>${q.rejected.length?`<div class="quality-table table-wrap"><table><thead><tr><th>CSV 행</th><th>청구 ID</th><th>제외 사유</th></tr></thead><tbody>${q.rejected.slice(0,100).map(x=>`<tr><td>${x.row}</td><td>${escapeHTML(x.claim_id)}</td><td>${escapeHTML(x.reason)}</td></tr>`).join('')}</tbody></table></div>`:''}</div></section>`;}
function dashboard(){return heading('숫자 너머의 근거를 확인하세요.','보험 청구의 이상징후를 살펴보고, 검토가 필요한 이유를 이해하세요.',actions())+sourceStrip()+metricGrid()+`<div class="dashboard-grid"><div class="left-column"><section class="panel"><div class="panel-head"><div><h2>월별 청구 추이</h2><p>청구 발생일 기준 · 전체 유효 청구</p></div><span class="chart-legend"><i class="legend-dot"></i>청구 건수</span></div>${monthlyChart()}<div class="chart-bottom"><span>${state.analysis.results[0].claim_date.slice(0,4)}년 청구 데이터</span><span>월별 집계 · 단위: 건</span></div></section><div class="subgrid"><section class="panel"><div class="panel-head"><h2>검토 우선순위 분포</h2></div>${donut()}</section><section class="panel"><div class="panel-head"><h2>보험 유형별 청구</h2><span class="muted" style="font-size:10px">단위: 건</span></div>${typeBars()}</section></div></div><div class="right-column">${briefing()}<section class="panel section-gap"><div class="panel-head"><h2>분석 기준 안내</h2>${icon('shield')}</div><div class="panel-body"><p class="muted" style="font-size:11px;line-height:1.95">규칙 점수 <strong>${Math.round(state.config.ruleWeight*100)}%</strong>와 모델 특이도 <strong>${Math.round((1-state.config.ruleWeight)*100)}%</strong>를 결합합니다. ${state.analysis.modelInfo.enabled?'과거 학습 구간의 분포와 비교한 상대적 지표입니다.':'표본이 부족하여 현재는 규칙 점수만 사용합니다.'}</p><button class="button link section-gap" data-action="settings">탐지 기준 조정 ${icon('arrow')}</button></div></section></div></div><section class="panel table-panel"><div class="panel-head"><div><h2>먼저 살펴볼 청구</h2><p>검토 우선순위 점수 상위 5건</p></div><button class="button link" data-tab="review">전체 보기 ${icon('arrow')}</button></div>${claimTable(sortedRows().slice(0,5))}<div class="table-foot"><span>근거를 확인하고, 담당자의 판단으로 검토를 진행하세요.</span><span>총 ${f(state.analysis.summary.count)}건</span></div></section>`+qualityHTML();}
function scatter(){const rows=state.analysis.results,stride=Math.max(1,Math.floor(rows.length/140)),selected=rows.filter((_,i)=>i%stride===0).concat(sortedRows().slice(0,10));return `<div class="chart"><svg viewBox="0 0 620 220" role="img" aria-label="규칙 점수와 모델 특이도 비교">${[0,25,50,75,100].map(n=>`<line class="grid-line" x1="40" x2="600" y1="${180-n*1.55}" y2="${180-n*1.55}"/><text x="29" y="${184-n*1.55}" text-anchor="end">${n}</text><text x="${40+n*5.6}" y="199" text-anchor="middle">${n}</text>`).join('')}${selected.map(r=>`<circle cx="${40+r.ruleScore*5.6}" cy="${180-(r.mlScore??0)*1.55}" r="3.5" fill="${r.priority==='높음'?'#c79660':r.priority==='보통'?'#8aaf97':'#c2d6c9'}" fill-opacity=".65"><title>${escapeHTML(r.claim_id)} · 규칙 ${r.ruleScore.toFixed(0)} / 모델 ${r.mlScore?.toFixed(0)??'미산출'}</title></circle>`).join('')}<text x="310" y="218" text-anchor="middle">규칙 점수 →</text><text x="45" y="13">모델 특이도 ↑</text></svg></div>`;}
function evaluationHTML(){if(!state.sample)return '';const metrics=E.evaluate(state.analysis,state.data.labels);if(!metrics.length)return '';return `<section class="panel section-gap"><div class="panel-head"><div><h2>가상 패턴 탐지 비교</h2><p>동일한 평가 구간 ${f(metrics[0].n)}건 · 레이블은 모델 입력에서 제외</p></div><span class="badge gray">실험용</span></div><div class="table-wrap"><table><thead><tr><th>분석 방식</th><th>Precision</th><th>Recall</th><th>F1</th><th>TP / FP / FN / TN</th></tr></thead><tbody>${metrics.map(m=>`<tr><td>${({rule:'규칙 탐지',ml:'Isolation Forest',combined:'통합 우선순위 높음'})[m.name]}</td><td>${m.precision.toFixed(3)}</td><td>${m.recall.toFixed(3)}</td><td>${m.f1.toFixed(3)}</td><td>${m.tp} / ${m.fp} / ${m.fn} / ${m.tn}</td></tr>`).join('')}</tbody></table></div><div class="table-foot">주입한 패턴을 기준으로 한 실험입니다. 실제 보험사기 탐지 성능으로 일반화할 수 없습니다.</div></section>`;}
function filteredRows(){return sortedRows().filter(r=>(state.type==='all'||r.insurance_type===state.type)&&(state.priority==='all'||r.priority===state.priority)&&(!state.search||r.claim_id.toLowerCase().includes(state.search.toLowerCase())||r.customer_id.toLowerCase().includes(state.search.toLowerCase())));}
function review(){const all=filteredRows(),pages=Math.max(1,Math.ceil(all.length/12));state.page=Math.min(state.page,pages);const shown=all.slice((state.page-1)*12,state.page*12);return heading('검토가 필요한 청구를 찾아보세요.','두 분석 방식의 결과를 비교하고, 각 청구의 탐지 근거를 확인하세요.',actions())+sourceStrip()+(state.comparison?`<div class="comparison-strip">기준 변경 결과 · 높음 ${state.comparison.high} → ${state.analysis.summary.high}건 · 보통 ${state.comparison.medium} → ${state.analysis.summary.medium}건 <button class="button link" data-action="clear-comparison">비교 닫기</button></div>`:'')+`<section class="panel"><div class="filters"><label class="search">${icon('search')}<input id="claim-search" placeholder="청구 ID 또는 고객 ID 검색" aria-label="청구 ID 또는 고객 ID 검색" value="${escapeHTML(state.search)}"></label><select id="type-filter" aria-label="보험 유형"><option value="all">전체 보험 유형</option>${Object.keys(state.analysis.summary.types).sort().map(x=>`<option value="${escapeHTML(x)}" ${state.type===x?'selected':''}>${escapeHTML(x)}</option>`).join('')}</select><select id="priority-filter" aria-label="검토 우선순위"><option value="all">전체 우선순위</option>${['높음','보통','낮음'].map(x=>`<option ${state.priority===x?'selected':''}>${x}</option>`).join('')}</select><button class="button" data-action="export">${icon('download')}결과 CSV</button></div><div id="review-table">${claimTable(shown,true)}</div><div class="table-foot"><span>${f(all.length)}건 중 ${all.length?(state.page-1)*12+1:0}–${Math.min(state.page*12,all.length)}건 · 점수 높은 순</span><div class="pagination"><button data-page="${Math.max(1,state.page-1)}" aria-label="이전 페이지">‹</button><button class="active" disabled>${state.page}</button><button data-page="${Math.min(pages,state.page+1)}" aria-label="다음 페이지">›</button></div></div></section><div class="subgrid"><section class="panel"><div class="panel-head"><div><h2>규칙과 모델의 시각</h2><p>일부 청구를 표시한 분포 비교</p></div></div>${scatter()}</section><section class="panel"><div class="panel-head"><h2>점수는 어떻게 계산하나요?</h2></div><div class="panel-body"><p class="muted" style="font-size:12px;line-height:2">5개 규칙의 탐지 비율을 규칙 점수로 계산합니다. 모델 특이도는 Isolation Forest 원점수가 학습 점수 분포에서 차지하는 상대 순위입니다.</p><div class="info-note">${icon('info')}규칙 ${Math.round(state.config.ruleWeight*100)}% + 모델 ${Math.round((1-state.config.ruleWeight)*100)}% · 높음 ${state.config.high}점 이상 · 보통 ${state.config.medium}점 이상</div><p class="muted" style="font-size:10px">${state.analysis.modelInfo.enabled?`학습 ${f(state.analysis.modelInfo.trainCount)}건 / 평가 ${f(state.analysis.modelInfo.testCount)}건. ${state.analysis.modelInfo.cutoff} 이전 날짜로 모델과 결측 대체값을 학습합니다. 학습 구간 점수는 후향적 분석입니다.`:'시간순으로 분리한 학습 표본이 20건 미만이어서 모델을 사용하지 않았습니다.'}</p></div></section></div>`+evaluationHTML()+qualityHTML();}
function ruleList(row){return `<div class="rule-list">${row.rules.map(x=>`<div class="rule-item ${x.hit?'hit':''}"><span class="rule-state">${x.hit?'!':'✓'}</span><div><h4>${x.name}</h4><p>${x.available?`관측 ${x.observed===null?'—':Number(x.observed.toFixed(2))}${x.id==='amount'?'배':x.id==='gap'?'일':'개'} · 기준 ${x.id==='gap'?'이하':'이상'} ${x.threshold}${x.id==='amount'?'배':x.id==='gap'?'일':''}`:'과거 비교 자료 부족 · 평가 보류'}</p></div><span class="badge ${x.hit?'amber':'gray'}">${!x.available?'보류':x.hit?'탐지':'미탐지'}</span></div>`).join('')}</div>`;}
function explanationHTML(x){return `<div class="ai-result"><h3>01 · 이상징후 요약</h3><p>${escapeHTML(x.summary)}</p><h3>02 · 분석 근거</h3><ul>${x.basis.map(b=>`<li>${escapeHTML(b)}</li>`).join('')}</ul><h3>03 · 추가 확인 사항</h3><ul>${x.checks.map(c=>`<li>${escapeHTML(c)}</li>`).join('')}</ul><p class="provider">${x.provider==='api'?'LLM API가 분석 JSON을 바탕으로 작성했습니다.':'API 미연결 · 검증된 수치로 만든 데모 설명입니다.'}</p></div>`;}
function detail(){const r=selectedRow(),result=state.explanations.get(cacheKey()),review=state.reviews.get(state.version+':'+r.claim_id)||{};return heading('하나의 청구, 근거를 연결해서.','분석된 수치와 비교 기준을 확인하고, 담당자의 다음 검토를 준비하세요.',`<button class="button" data-tab="review">${icon('list')}검토 목록</button><button class="button" data-action="evidence">${icon('code')}분석 JSON</button>`)+`<div style="display:flex;gap:12px;align-items:center;margin-bottom:22px"><label for="claim-select" class="muted" style="font-size:11px">청구 선택</label><select id="claim-select" style="min-width:250px;max-width:100%">${sortedRows().map(x=>`<option value="${escapeHTML(x.claim_id)}" ${x.claim_id===r.claim_id?'selected':''}>${escapeHTML(x.claim_id)} · ${x.priority} · ${x.score.toFixed(1)}점</option>`).join('')}</select><span class="badge gray">${r.partition} 구간</span></div>${pipeline()}<div class="detail-grid"><div><section class="panel detail-summary"><div class="claim-heading"><strong>${escapeHTML(r.claim_id)}</strong>${priorityBadge(r.priority)}</div><div class="key-values"><div><span>청구 금액</span><strong>${E.money(r.amount)}</strong></div><div><span>청구일</span><strong>${r.claim_date}</strong></div><div><span>보험 유형 / 진료 유형</span><strong>${escapeHTML(r.insurance_type)} / ${escapeHTML(r.treatment_type)}</strong></div><div><span>고객 / 의료기관</span><strong>${escapeHTML(r.customer_id)} / ${escapeHTML(r.hospital_id)}</strong></div></div><div class="score-block"><div class="score-circle">${r.score.toFixed(1)}</div><div><h3>검토 우선순위 점수</h3><p>설정된 분석 기준에 따른 상대적 검토 지표</p><div class="small-scores"><div>규칙 점수<strong>${r.ruleScore.toFixed(1)}</strong></div><div>모델 특이도<strong>${r.mlScore===null?'미산출':r.mlScore.toFixed(1)}</strong></div></div></div></div></section><section class="panel section-gap"><div class="panel-head"><h2>규칙별 탐지 근거</h2><span class="badge gray">${state.config.windowDays}일 관찰</span></div>${ruleList(r)}</section><section class="panel section-gap"><div class="panel-head"><h2>비교 가능한 지표</h2></div><div class="panel-body">${r.peerMedian?`<div class="comparison-row"><p><span>해당 청구 금액</span><strong>${E.money(r.amount)}</strong></p><div class="bar-track"><div class="bar-fill" style="width:${r.amount/Math.max(r.amount,r.peerMedian)*100}%;background:#538e71"></div></div></div><div class="comparison-row"><p><span>이전 동일 진료 중앙값 (${f(r.peerCount)}건)</span><strong>${E.money(r.peerMedian)}</strong></p><div class="bar-track"><div class="bar-fill" style="width:${r.peerMedian/Math.max(r.amount,r.peerMedian)*100}%"></div></div></div>`:'<div class="info-note warning">동일 진료의 이전 청구 표본이 부족하여 금액 비교를 보류했습니다.</div>'}<div class="key-values section-gap"><div><span>최근 청구 / 의료기관 수</span><strong>${r.recentCount}건 / ${r.recentHospitals}곳</strong></div><div><span>이전 청구와의 간격</span><strong>${r.gapDays===null?'이전 청구 없음':r.gapDays+'일'}</strong></div></div><div class="info-note">${icon('info')}특징값이 크다는 사실만으로 모델 점수의 직접적인 원인이라고 단정하지 않습니다.</div></div></section></div><div><section class="panel ai-panel"><div class="ai-status"><h2>${icon('spark')}AI 검토 어시스턴트</h2><span class="badge ${state.api?'green':'gray'}">${state.api?'LLM 연결':'데모 모드'}</span></div><div id="explanation-content">${result?explanationHTML(result):`<div class="ai-placeholder"><span class="big-spark">${icon('spark')}</span><h3>숫자를 업무의 언어로</h3><p>이 청구의 분석 근거를 요약하고,<br>확인할 항목을 정리해 드립니다.</p><button class="button primary" data-action="explain">${icon('spark')}근거 기반 설명 생성</button></div>`}</div>${result?'<button class="button link section-gap" data-action="explain">설명 다시 생성</button>':''}<form class="question-form" id="question-form"><input id="question" maxlength="1000" aria-label="선택한 청구에 대해 질문" placeholder="이 청구에 대해 물어보세요"><button class="button primary" type="submit" aria-label="질문 전송">${icon('send')}</button></form><div class="suggestions">${['왜 검토가 필요한가요?','금액을 비교해 주세요','다음에 무엇을 확인하나요?'].map(x=>`<button class="suggestion" data-question="${x}">${x}</button>`).join('')}</div><div id="chat-result">${result?.answer?`<div class="chat-answer"><strong>질문에 대한 답변</strong>${escapeHTML(result.answer)}</div>`:''}</div><p class="muted" style="font-size:9px;margin-top:14px;line-height:1.8">${state.api?'설명 생성 시 고객·기관 ID를 제외한 분석 근거가 LLM API에 전달됩니다.':'실제 LLM API가 연결되지 않았습니다. 데모는 분석 수치에 기반한 정해진 설명과 답변을 제공합니다.'}</p></section><section class="panel section-gap"><div class="panel-head"><h2>담당자 검토 기록</h2></div><div class="panel-body"><p class="muted" style="font-size:11px">근거 확인 후 검토 상태와 메모를 남기세요.</p><form class="review-form" id="review-form"><label for="review-note">검토 메모</label><textarea id="review-note" maxlength="2000" placeholder="확인한 서류, 추가 확인 사유 등">${escapeHTML(review.note||'')}</textarea><div class="row"><select id="review-status" aria-label="검토 상태">${['미검토','추가 확인 필요','검토 완료'].map(s=>`<option ${review.status===s?'selected':''}>${s}</option>`).join('')}</select><button type="submit" class="button primary">저장</button></div></form><p class="muted" style="font-size:9px;margin-top:10px">메모는 현재 브라우저 탭에서 유지되며 보고서에 반영됩니다.</p></div></section></div></div>`;}
function report(){const a=state.analysis,s=a.summary,r=selectedRow(),evidence=E.evidence(r,a),explanation=state.explanations.get(cacheKey())||E.demoExplain(evidence),review=state.reviews.get(state.version+':'+r.claim_id);return heading('검토의 근거를 한 장에.','실제 분석 결과와 적용 기준을 정리해 공유 가능한 보고서를 만드세요.',`<button class="button" data-action="export">${icon('download')}분석 결과 CSV</button><button class="button primary" data-action="print">${icon('file')}인쇄 / PDF 저장</button>`)+`<div class="report-layout"><article class="report-paper" id="report-paper"><div class="report-brand">InsureLens <span class="muted" style="font-size:10px;font-weight:400">/ ANALYSIS REPORT</span></div><span class="eyebrow">EVIDENCE FOR BETTER DECISIONS</span><h2>보험 청구 이상징후 분석 보고서</h2><div class="report-meta">분석 데이터: ${escapeHTML(state.source)} · 청구 기간 ${a.results[0].claim_date} — ${a.results.at(-1).claim_date}<br>원본 ${f(a.quality.inputCount)}건 / 유효 ${f(s.count)}건 / 제외 ${f(a.quality.rejected.length)}건</div><div class="report-stats"><div class="report-stat"><span>전체 청구 금액</span><strong>${(s.total/1e8).toFixed(2)}억 원</strong></div><div class="report-stat"><span>높은 검토 우선순위</span><strong>${f(s.high)}건</strong></div><div class="report-stat"><span>추가 확인 대상</span><strong>${f(s.medium)}건</strong></div></div><section class="report-section"><h3>01 · 분석 기준</h3><div class="report-settings">${[['관찰 기간',state.config.windowDays+'일'],['반복 청구 기준',state.config.repeatCount+'건 이상'],['동일 진료 금액 비율',state.config.amountRatio+'배 이상'],['의료기관 수',state.config.hospitalCount+'곳 이상'],['짧은 청구 간격',state.config.shortGap+'일 이하'],['최소 비교 표본',state.config.minPeers+'건'],['규칙 / 모델 가중치',Math.round(state.config.ruleWeight*100)+'% / '+Math.round((1-state.config.ruleWeight)*100)+'%'],['우선순위 기준','높음 '+state.config.high+' / 보통 '+state.config.medium]].map(([k,v])=>`<div>${k}<strong>${v}</strong></div>`).join('')}</div></section><section class="report-section"><h3>02 · 선택 청구의 분석 근거</h3><p><strong>${escapeHTML(r.claim_id)}</strong> · ${E.money(r.amount)} · ${escapeHTML(r.treatment_type)} · ${r.claim_date}<br>검토 점수 ${r.score.toFixed(1)} / 100 · 우선순위 ${r.priority} · 규칙 ${r.ruleScore.toFixed(1)} / 모델 ${r.mlScore?.toFixed(1)??'미산출'}</p><ul>${explanation.basis.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ul></section><section class="report-section"><h3>03 · 설명 및 추가 확인 사항 <span class="badge gray">${explanation.provider==='api'?'LLM 설명':'데모 설명'}</span></h3><p>${escapeHTML(explanation.summary)}</p><ul>${explanation.checks.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ul></section>${review?`<section class="report-section"><h3>04 · 담당자 검토 기록</h3><p>상태: ${escapeHTML(review.status)}<br>${escapeHTML(review.note||'메모 없음')}</p></section>`:''}<section class="report-section"><h3>해석 범위</h3><p>이 점수는 검토 순서를 돕는 지표이며 보험사기 확률 또는 지급 판단이 아닙니다. 임계값과 가중치는 실험 설정입니다. ${a.modelInfo.enabled?`날짜 ${a.modelInfo.cutoff} 이전 ${a.modelInfo.trainCount}건으로 모델을 학습했으며, 학습 구간 점수는 후향적 분석입니다.`:'학습 표본 부족으로 모델 분석을 수행하지 않았습니다.'} ${state.sample?'가상 패턴에 대한 평가를 실제 보험사기 탐지 성능으로 해석할 수 없습니다.':''}</p></section><div class="report-sign"><span>InsureLens · 데이터 기반 의사결정 지원</span><span>최종 확인: 담당 심사자</span></div></article><aside class="report-aside"><section class="panel"><div class="panel-body"><h3>보고서에 포함할 청구</h3><p>상세 화면에서 검토한 청구를 선택하세요.</p><select id="report-claim" style="width:100%;margin-top:13px">${sortedRows().map(x=>`<option value="${escapeHTML(x.claim_id)}" ${r.claim_id===x.claim_id?'selected':''}>${escapeHTML(x.claim_id)} · ${x.score.toFixed(1)}점</option>`).join('')}</select><button class="button" data-tab="detail">${icon('spark')}상세 분석 확인</button></div></section><section class="panel"><div class="panel-body"><h3>PDF로 저장하기</h3><p>아래 버튼을 누른 뒤 인쇄 창의 대상을 ‘PDF로 저장’으로 선택하세요.</p><button class="button primary" data-action="print">${icon('file')}보고서 인쇄 / PDF 저장</button><button class="button" data-action="evidence">${icon('code')}근거 JSON 확인</button></div></section><section class="panel briefing"><h3>숫자와 설명을 함께</h3><p style="margin-top:10px;font-size:11px">현재 데이터, 실제 점수, 적용한 기준과 추가 확인 항목이 보고서에 반영됩니다.</p></section></aside></div>`;}
function about(){return heading('과제의 목적에 맞게 설계했습니다.','한국신용정보원 보험데이터부 · 데이터 기반 의사결정 + LLM 설명 지원',`<button class="button primary" data-tab="dashboard">데모 분석 보기 ${icon('arrow')}</button>`)+`<section class="about-hero"><span class="eyebrow">PROJECT ALIGNMENT</span><h2>지표를 읽는 것에서, 판단을 준비하는 것까지.</h2><p>InsureLens는 보험 청구 데이터를 분석해 검토 우선순위를 만들고, 분석 근거를 자연어로 설명해 담당자의 추가 확인을 돕는 의사결정 지원 페이지입니다. 과제에 제시된 ‘분석 지표 → 해석·요약 → 업무 목적에 맞는 의미 부여 → 의사결정 지원’ 흐름을 보험 심사 업무에 적용했습니다.</p></section><div class="about-cards"><section class="panel">${icon('chart')}<h3>데이터 기반 지표</h3><p>실제 CSV를 읽고 검증합니다. 과거 청구 특징과 규칙, Isolation Forest로 재현 가능한 점수를 계산합니다.</p></section><section class="panel">${icon('spark')}<h3>LLM 설명 지원</h3><p>선택 청구의 구조화된 분석 근거를 전달해 요약·근거·확인 사항을 생성합니다. API 연결 전에는 데모 설명을 명시합니다.</p></section><section class="panel">${icon('shield')}<h3>업무 의사결정 지원</h3><p>검토 대상을 찾고, 기준을 조정하고, 담당자 메모와 보고서로 다음 업무를 준비합니다. 최종 결정은 담당자가 합니다.</p></section></div><section class="panel section-gap"><div class="panel-head"><h2>과제 요구사항과 구현 기능</h2><span class="badge green">보험사기 예방 주제 적용</span></div><div class="table-wrap"><table class="fit-table"><thead><tr><th>과제의 요구</th><th>이 페이지에서 수행하는 일</th><th>구현 상태</th></tr></thead><tbody>${[['업무에 필요한 분석 지표','청구 추이, 금액, 반복 청구, 여러 기관 이용, 동일 진료 금액 비교','구현'],['LLM으로 지표 해석·요약','근거 JSON을 읽는 설명·질의응답 API와 실패 시 데모 설명','API 키 연결 필요'],['업무 목적에 맞는 의미 부여','보험 청구 검토 우선순위, 근거와 추가 확인 사항 제시','구현'],['의사결정 지원 AI Agent','입력 검증 → 분석 → 근거 구성 → 설명 → 담당자 검토 → 보고서의 단계별 워크플로','지원형 워크플로'],['예시 데이터 구현 또는 컨셉 설계','가상 청구 2,000건 + 별도 주입 패턴 레이블 + CSV 업로드','작동 데모'],['활용 기술·플랫폼','HTML / CSS / JavaScript. JavaScript 허용 여부는 사용자 확인을 반영','언어 변경 반영']].map(([a,b,c])=>`<tr><td>${a}</td><td>${b}</td><td><span class="badge ${c==='API 키 연결 필요'?'amber':'green'}">${c}</span></td></tr>`).join('')}</tbody></table></div></section><section class="panel section-gap"><div class="panel-head"><h2>발표에서 설명할 핵심과 현재 한계</h2></div><div class="panel-body"><div class="info-note">${icon('check')}이 과제에 적합한 주제입니다. 분석 결과를 근거로 해석하고 검토 업무에 연결하는 흐름을 시연할 수 있습니다.</div><p class="muted" style="font-size:12px;line-height:2.1">실제 LLM을 사용한 시연에는 서버 환경변수의 API 키가 필요합니다. 현재 연결 상태는 상세 화면에 표시합니다. 데모 설명을 실제 LLM 출력으로 소개하지 마세요. 모델은 가상 패턴의 분포상 특이도를 측정하며, 보험사기 정답이나 최적의 심사 기준을 학습한 모델은 아닙니다. 감독 없이 업무를 수행하는 에이전트로 표현하기보다, 담당자를 지원하는 단계별 분석 워크플로로 설명하는 것이 정확합니다.</p></div></section>`;}
function render(){if(!state.analysis)return;const known=navItems.find(x=>x[0]===state.tab)||navItems[0];$('#navigation').innerHTML=navItems.map(([id,ic,label])=>`<a href="#${id}" class="${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''} title="${label}">${icon(ic)}<span class="nav-text">${label}</span>${id==='review'?`<span class="nav-count">${state.analysis.summary.high}</span>`:''}</a>`).join('');$('#page-label').textContent=known[2];$('#main').innerHTML=({dashboard,review,detail,report,about}[state.tab]||dashboard)();document.title='InsureLens · '+known[2];bindPage();}
function bindPage(){const search=$('#claim-search');if(search)search.addEventListener('input',()=>{state.search=search.value;state.page=1;const pos=search.selectionStart;render();const next=$('#claim-search');next.focus();next.setSelectionRange(pos,pos);});$('#type-filter')?.addEventListener('change',ev=>{state.type=ev.target.value;state.page=1;render();});$('#priority-filter')?.addEventListener('change',ev=>{state.priority=ev.target.value;state.page=1;render();});for(const id of ['claim-select','report-claim'])$('#'+id)?.addEventListener('change',ev=>{state.selected=ev.target.value;render();});$('#question-form')?.addEventListener('submit',ev=>{ev.preventDefault();const q=$('#question').value.trim();if(q)generateExplanation(q);});$('#review-form')?.addEventListener('submit',ev=>{ev.preventDefault();state.reviews.set(state.version+':'+state.selected,{status:$('#review-status').value,note:$('#review-note').value});toast('검토 기록을 저장했습니다. 보고서에 반영됩니다.');});}
async function generateExplanation(question=''){const r=selectedRow(),key=cacheKey(),payload=E.evidence(r,state.analysis);const button=$('[data-action="explain"]');if(button){button.disabled=true;button.textContent='근거를 확인하고 있습니다…';}let result;try{if(state.api){const response=await fetch('/api/explain',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({evidence:payload,question}),signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error('API 요청 실패');result=await response.json();if(typeof result.summary!=='string'||!Array.isArray(result.basis)||!Array.isArray(result.checks))throw Error('잘못된 응답');}else result=E.demoExplain(payload,question);}catch{result=E.demoExplain(payload,question);toast('API 연결에 실패해 분석 근거 기반 데모 설명을 표시합니다.');}state.explanations.set(key,result);if(cacheKey()===key&&state.tab==='detail')render();}
function download(name,content,type='text/csv;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showSettings(){
  const fields=[['windowDays','관찰 기간 (일)',1,365,1],['repeatCount','반복 청구 (건 이상)',2,50,1],['amountRatio','동일 진료 금액 (배 이상)',1.1,20,.1],['hospitalCount','의료기관 (곳 이상)',2,30,1],['shortGap','짧은 간격 (일 이하)',0,30,1],['minPeers','최소 비교 표본 (건)',1,200,1],['high','높음 기준 점수',1,100,1],['medium','보통 기준 점수',0,99,1]];
  $('#settings-form').innerHTML=`<div class="setting-grid">${fields.map(([id,label,min,max,step])=>`<div class="setting-field"><label for="setting-${id}">${label}</label><input id="setting-${id}" name="${id}" type="number" min="${min}" max="${max}" step="${step}" value="${state.config[id]}" required></div>`).join('')}<div class="setting-field wide"><label for="setting-ruleWeight">규칙 가중치 <output id="weight-output">${Math.round(state.config.ruleWeight*100)}% · 모델 ${Math.round((1-state.config.ruleWeight)*100)}%</output></label><input name="ruleWeight" id="setting-ruleWeight" type="range" min="0" max="1" step=".05" value="${state.config.ruleWeight}"></div><div class="setting-field wide"><label for="setting-contamination">모델 이상 비율 가정</label><input id="setting-contamination" name="contamination" type="number" min=".01" max=".3" step=".01" value="${state.config.contamination}" required></div></div><p class="settings-note">학습 분포의 상대 순위로 모델 점수를 계산합니다. 이 비율 가정은 사기 발생률이 아닙니다. 가중치와 기준은 검증된 최적값이 아닙니다.</p><div id="settings-error" class="error" hidden></div><div class="dialog-actions"><button type="button" class="button" id="reset-settings">기본값 복원</button><button type="submit" class="button primary">변경하고 다시 분석</button></div>`;
  const updateWeight=()=>{const value=Number($('#setting-ruleWeight').value);$('#weight-output').textContent=Math.round(value*100)+'% · 모델 '+Math.round((1-value)*100)+'%';};
  $('#setting-ruleWeight').addEventListener('input',updateWeight);
  $('#reset-settings').addEventListener('click',()=>{for(const [key,value] of Object.entries(E.defaults)){const input=$('#setting-'+key);if(input)input.value=value;}updateWeight();});
  $('#settings-dialog').showModal();
}
async function reanalyze(raw,options={}){$('#loading').hidden=false;await new Promise(r=>setTimeout(r,40));try{const analysis=E.analyze(raw,options.config||state.config);if(options.compare)state.comparison=state.analysis.summary;else state.comparison=null;state.analysis=analysis;state.config=analysis.config;if(options.data){state.data=options.data;state.source=options.source;state.sample=options.sample;state.version++;state.explanations.clear();state.search='';state.type='all';state.priority='all';state.page=1;}if(!analysis.results.some(x=>x.claim_id===state.selected))state.selected=sortedRows()[0].claim_id;try{localStorage.setItem('insurelens-settings',JSON.stringify(state.config));}catch{}render();return true;}catch(error){toast(error.message);return false;}finally{$('#loading').hidden=true;}}
async function upload(file){if(!file)return;if(file.size>5*1024*1024){$('#upload-error').textContent='5MB 이하의 CSV를 선택해 주세요.';$('#upload-error').hidden=false;return;}try{const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer()),raw=E.parseCSV(text);const okay=await reanalyze(raw,{data:{rows:raw,labels:{}},source:file.name,sample:false});if(okay){$('#data-dialog').close();toast('CSV 분석을 완료했습니다. 제외된 행은 데이터 품질에서 확인하세요.');}else throw Error('유효한 청구가 없습니다. 데이터 형식을 확인하세요.');}catch(error){$('#upload-error').textContent=error instanceof TypeError?'UTF-8로 저장한 CSV를 업로드해 주세요.':error.message;$('#upload-error').hidden=false;}}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action],[data-tab],[data-select],[data-page],[data-question],.close-dialog');if(!el)return;if(el.matches('.close-dialog'))el.closest('dialog').close();if(el.dataset.tab)go(el.dataset.tab);if(el.dataset.select){state.selected=el.dataset.select;go('detail');window.scrollTo({top:0,behavior:'instant'});}if(el.dataset.page){state.page=Number(el.dataset.page);render();}if(el.dataset.question)generateExplanation(el.dataset.question);const a=el.dataset.action;if(a==='data'){$('#upload-error').hidden=true;$('#data-dialog').showModal();}if(a==='settings')showSettings();if(a==='evidence'){$('#evidence-json').textContent=JSON.stringify(E.evidence(selectedRow(),state.analysis),null,2);$('#evidence-dialog').showModal();}if(a==='explain')generateExplanation();if(a==='quality'){if(state.tab!=='review'&&state.tab!=='dashboard'){go('review');setTimeout(()=>$('#quality-section')?.scrollIntoView({behavior:'smooth'}),50);}else $('#quality-section')?.scrollIntoView({behavior:'smooth'});}if(a==='export')download('insurelens_analysis.csv',E.csv(sortedRows(),[...E.columns,'score','priority','ruleScore','mlScore','partition']));if(a==='print'){window.print();}if(a==='clear-comparison'){state.comparison=null;render();}});
$('#settings-form').addEventListener('submit',async ev=>{ev.preventDefault();const form=new FormData(ev.target),cfg={...state.config};for(const [k,v]of form)cfg[k]=Number(v);if(cfg.medium>=cfg.high){$('#settings-error').textContent='보통 기준은 높음 기준보다 작아야 합니다.';$('#settings-error').hidden=false;return;}if(await reanalyze(state.data.rows,{config:cfg,compare:true})){$('#settings-dialog').close();go('review');toast('기준을 변경하고 분석을 다시 계산했습니다.');}});
$('#csv-file').addEventListener('change',ev=>upload(ev.target.files[0]));
const drop=$('.dropzone');['dragenter','dragover'].forEach(type=>drop.addEventListener(type,ev=>{ev.preventDefault();drop.classList.add('drag');}));['dragleave','drop'].forEach(type=>drop.addEventListener(type,ev=>{ev.preventDefault();drop.classList.remove('drag');if(type==='drop')upload(ev.dataTransfer.files[0]);}));
$('#use-sample').addEventListener('click',async()=>{const data=E.sample();if(await reanalyze(data.rows,{data,source:'가상 보험 청구 데이터',sample:true})){$('#data-dialog').close();toast('샘플 2,000건을 불러왔습니다.');}});
$('#download-sample').addEventListener('click',()=>download('sample_claims.csv',E.csv(E.sample().rows)));
$('#help-button').innerHTML=icon('help');$('#help-button').addEventListener('click',()=>go('about'));$('#upload-icon').innerHTML=icon('upload');$('#user-icon').innerHTML=icon('user');
window.addEventListener('hashchange',()=>{state.tab=navItems.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'dashboard';render();window.scrollTo({top:0,behavior:'instant'});});
async function init(){state.tab=navItems.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'dashboard';if(!await reanalyze(state.data.rows)){state.config={...E.defaults};await reanalyze(state.data.rows);}if(window.INSURELENS_SERVER){try{const res=await fetch('/api/status',{signal:AbortSignal.timeout(3000)});if(res.ok){const status=await res.json();state.api=!!status.connected;state.apiNote=status.connected?'LLM 연결':'데모 설명 모드';if(state.tab==='detail')render();}}catch{}}}
init();
